### 2.2 Cluster Management

```python
import redis
import redis.exceptions
from typing import List, Dict, Any
import asyncio
import logging

class RedisClusterManager:
    """Redis cluster management and monitoring"""

    def __init__(self, cluster_nodes: List[str]):
        self.cluster_nodes = cluster_nodes
        self.cluster = redis.RedisCluster(
            startup_nodes=[{"host": node.split(':')[0], "port": int(node.split(':')[1])}
                          for node in cluster_nodes],
            decode_responses=True,
            skip_full_coverage_check=True,
            health_check_interval=30
        )

    async def get_cluster_info(self) -> Dict[str, Any]:
        """Get comprehensive cluster information"""
        try:
            cluster_info = self.cluster.cluster_info()
            nodes_info = self.cluster.cluster_nodes()

            # Parse cluster state
            active_masters = sum(1 for node in nodes_info.values()
                               if 'master' in node.get('flags', []) and 'fail' not in node.get('flags', []))

            active_replicas = sum(1 for node in nodes_info.values()
                                if 'slave' in node.get('flags', []) and 'fail' not in node.get('flags', []))

            return {
                'cluster_state': cluster_info.get('cluster_state'),
                'cluster_slots_assigned': cluster_info.get('cluster_slots_assigned'),
                'cluster_slots_ok': cluster_info.get('cluster_slots_ok'),
                'cluster_slots_pfail': cluster_info.get('cluster_slots_pfail'),
                'cluster_slots_fail': cluster_info.get('cluster_slots_fail'),
                'cluster_known_nodes': cluster_info.get('cluster_known_nodes'),
                'active_masters': active_masters,
                'active_replicas': active_replicas,
                'nodes_detail': nodes_info
            }
        except Exception as e:
            logging.error(f"Failed to get cluster info: {e}")
            return {'error': str(e)}

    async def check_cluster_health(self) -> Dict[str, Any]:
        """Comprehensive cluster health check"""
        health_status = {
            'overall_health': 'healthy',
            'issues': [],
            'warnings': [],
            'node_status': {}
        }

        try:
            cluster_info = await self.get_cluster_info()

            # Check cluster state
            if cluster_info.get('cluster_state') != 'ok':
                health_status['overall_health'] = 'degraded'
                health_status['issues'].append(f"Cluster state: {cluster_info.get('cluster_state')}")

            # Check slot coverage
            if cluster_info.get('cluster_slots_assigned', 0) < 16384:
                health_status['overall_health'] = 'critical'
                health_status['issues'].append("Incomplete slot coverage")

            # Check failed slots
            if cluster_info.get('cluster_slots_fail', 0) > 0:
                health_status['overall_health'] = 'critical'
                health_status['issues'].append(f"Failed slots: {cluster_info.get('cluster_slots_fail')}")

            # Check node availability
            for node_id, node_info in cluster_info.get('nodes_detail', {}).items():
                node_flags = node_info.get('flags', [])
                if 'fail' in node_flags:
                    health_status['overall_health'] = 'critical'
                    health_status['issues'].append(f"Failed node: {node_id}")
                elif 'pfail' in node_flags:
                    health_status['warnings'].append(f"Possibly failed node: {node_id}")

                health_status['node_status'][node_id] = {
                    'status': 'failed' if 'fail' in node_flags else 'healthy',
                    'role': 'master' if 'master' in node_flags else 'replica',
                    'slots': node_info.get('slots', [])
                }

        except Exception as e:
            health_status['overall_health'] = 'critical'
            health_status['issues'].append(f"Health check failed: {e}")

        return health_status

    async def perform_failover(self, node_id: str, force: bool = False) -> Dict[str, Any]:
        """Perform manual failover for a specific node"""
        try:
            # Get node information
            nodes_info = self.cluster.cluster_nodes()
            target_node = nodes_info.get(node_id)

            if not target_node:
                return {'success': False, 'error': 'Node not found'}

            if 'slave' not in target_node.get('flags', []):
                return {'success': False, 'error': 'Can only failover to replica nodes'}

            # Execute failover
            node_connection = redis.Redis(
                host=target_node['host'],
                port=target_node['port']
            )

            if force:
                result = node_connection.cluster_failover('FORCE')
            else:
                result = node_connection.cluster_failover()

            return {
                'success': True,
                'node_id': node_id,
                'force': force,
                'result': result
            }

        except Exception as e:
            return {'success': False, 'error': str(e)}
