### 8.1 Rolling Updates

```python
class RedisMaintenanceManager:
    """Manage Redis maintenance procedures"""

    async def perform_rolling_update(self, cluster_nodes: List[str],
                                   update_command: str) -> Dict[str, Any]:
        """Perform rolling update on Redis cluster"""
        update_result = {
            'started_at': datetime.utcnow().isoformat(),
            'nodes_updated': [],
            'failed_nodes': [],
            'success': False
        }

        try:
            for node in cluster_nodes:
                node_result = await self._update_single_node(node, update_command)

                if node_result['success']:
                    update_result['nodes_updated'].append(node)
                else:
                    update_result['failed_nodes'].append({
                        'node': node,
                        'error': node_result['error']
                    })

                # Wait between updates
                await asyncio.sleep(30)

            update_result['success'] = len(update_result['failed_nodes']) == 0
            update_result['completed_at'] = datetime.utcnow().isoformat()

        except Exception as e:
            update_result['error'] = str(e)
            update_result['failed_at'] = datetime.utcnow().isoformat()

        return update_result

    async def _update_single_node(self, node: str, update_command: str) -> Dict[str, Any]:
        """Update a single Redis node"""
        try:
            host, port = node.split(':')
            redis_client = redis.Redis(host=host, port=int(port))

            # Check if node is replica
            info = redis_client.info('replication')
            is_master = info.get('role') == 'master'

            if not is_master:
                # For replicas, just restart
                result = subprocess.run(update_command.split(), capture_output=True, text=True)
                return {'success': result.returncode == 0, 'output': result.stdout}
            else:
                # For masters, perform failover first
                failover_result = await self._failover_master(node)
                if not failover_result['success']:
                    return failover_result

                # Now update the former master
                result = subprocess.run(update_command.split(), capture_output=True, text=True)
                return {'success': result.returncode == 0, 'output': result.stdout}

        except Exception as e:
            return {'success': False, 'error': str(e)}
